// Register custom commands
MinecraftForge.EVENT_BUS.addListener(this::registerCommands);

private void registerCommands(RegisterCommandsEvent event) {
    CommandDispatcher<CommandSourceStack> dispatcher = event.getDispatcher();

    // Simple literal command
    LiteralArgumentBuilder<CommandSourceStack> myCommand = Commands.literal("mymod")
        .requires(source -> source.hasPermission(2)) // Permission level
        .then(Commands.literal("hello")
            .executes(context -> {
                context.getSource().sendSuccess(
                    new TextComponent("Hello from my mod!"), true
                );
                return 1;
            })
        )
        .then(Commands.literal("config")
            .then(Commands.argument("value", IntegerArgumentType.integer())
                .executes(context -> {
                    int value = IntegerArgumentType.getInteger(context, "value");
                    // Set config value
                    return value;
                })
            )
        );

    dispatcher.register(myCommand);
}
